<script setup lang="ts">
import {onMounted,ref,nextTick,computed} from 'vue';
import {useI18n} from 'vue-i18n';
import {useRoute} from 'vue-router';
import {calculate,detail,recommend,type Filters,type Nutrition,type Recipe} from '../api/recipes';
import {recipeLabel,ingredientLabel,scaleIngredients} from '../recipe-labels';
import {useDashboard,isPublicDemo} from '../stores/dashboard';
import FoodPhoto from '../components/FoodPhoto.vue';
const {t,te,locale}=useI18n();const route=useRoute();const store=useDashboard();
const filters=ref<Filters>({max_calories:700,min_protein_g:15,max_price_thb:150,max_total_minutes:40,max_cleanup_minutes:10});
const saving=ref(false);const saved=ref(false);
const recipes=ref<Recipe[]>([]);const selected=ref<Recipe|null>(null);const detailPanel=ref<HTMLElement|null>(null);const calculated=ref<Nutrition|null>(null);const servings=ref(2);const loading=ref(false);const error=ref('');let calculationGeneration=0;
const ingredientAmounts=computed(()=>{try{return selected.value?scaleIngredients(selected.value.ingredients??[],selected.value.servings,servings.value):[];}catch{return [];}});
async function logSelected(){if(!selected.value||!calculated.value)return;saving.value=true;saved.value=false;error.value='';try{await store.save('food-entries',{recipe_slug:selected.value.slug,servings:servings.value});saved.value=true;}catch(e){fail(e);}finally{saving.value=false;}}
function fail(e:unknown){const message=e instanceof Error?e.message:String(e);error.value=te(message)?t(message):t('requestFailed');}
async function search(){loading.value=true;error.value='';try{recipes.value=await recommend(filters.value,store.data?.market.country_code??'TH');}catch(e){fail(e);}finally{loading.value=false;}}
async function openRecipe(slug:string){error.value='';saved.value=false;calculationGeneration++;try{selected.value=await detail(slug);servings.value=selected.value.servings;calculated.value=selected.value.nutrition;await nextTick();detailPanel.value?.focus();detailPanel.value?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});}catch(e){fail(e);}}
async function recalculate(){if(!selected.value)return;const generation=++calculationGeneration;error.value='';saved.value=false;calculated.value=null;try{const result=await calculate(selected.value.slug,servings.value);if(generation===calculationGeneration)calculated.value=result;}catch(e){if(generation===calculationGeneration)fail(e);}}
onMounted(async()=>{await search();if(typeof route.query.recipe==='string'){await openRecipe(route.query.recipe);const portions=Number(route.query.portions);if(Number.isInteger(portions)&&portions>=1&&portions<=30){servings.value=portions;await recalculate();}}});
</script>
<template><div class="shell">
<section class="panel"><h1>{{t('filterTitle')}}</h1><form @submit.prevent="search"><div class="filters"><label>{{t('maxCalories')}}<input v-model.number="filters.max_calories" type="number" min="1" required></label><label>{{t('minProtein')}}<input v-model.number="filters.min_protein_g" type="number" min="0" required></label><label>{{t('budget')}}<input v-model.number="filters.max_price_thb" type="number" min="1" required></label><label>{{t('totalTime')}}<input v-model.number="filters.max_total_minutes" type="number" min="1" required></label><label>{{t('cleanupMax')}}<input v-model.number="filters.max_cleanup_minutes" type="number" min="0" required></label></div><button :disabled="loading">{{t(loading?'loading':'findMeal')}}</button></form></section>
<p v-if="error" class="error" role="alert">{{error}}</p>
<section><div class="section-title"><h2>{{t('recommended')}}</h2><span aria-live="polite">{{t('matches',{value:recipes.length})}}</span></div><p v-if="loading">{{t('loading')}}</p><p v-else-if="!recipes.length">{{t('emptyRecipes')}}</p><div class="cards"><article v-for="recipe in recipes" :key="recipe.slug" class="card"><FoodPhoto :slug="recipe.slug" :alt="recipeLabel(recipe.slug,locale,recipe.title)"/><div class="eyebrow">{{recipe.total_minutes}} {{t('minutes')}} · {{recipe.cleanup_minutes}} {{t('minutes')}} {{t('cleanup')}}</div><h3>{{recipeLabel(recipe.slug,locale,recipe.title)}}</h3><p>{{recipeLabel(recipe.slug,locale,recipe.description,true)}}</p><div class="macros"><span>{{recipe.nutrition.per_serving.calories}} {{t('kcal')}}</span><span>{{recipe.nutrition.per_serving.protein_g}} {{t('grams')}} {{t('protein')}}</span><span>{{recipe.nutrition.per_serving.price_thb===null?t('priceUnknown'):'≈ ฿'+recipe.nutrition.per_serving.price_thb}}</span></div><button class="secondary" @click="openRecipe(recipe.slug)">{{t('viewRecipe')}}</button></article></div></section>
<section v-if="selected" ref="detailPanel" tabindex="-1" class="panel detail" :aria-label="recipeLabel(selected.slug,locale,selected.title)"><button class="close" @click="selected=null;calculationGeneration++">{{t('close')}} ×</button><h2>{{recipeLabel(selected.slug,locale,selected.title)}}</h2><FoodPhoto :slug="selected.slug" :alt="recipeLabel(selected.slug,locale,selected.title)"/><p>{{recipeLabel(selected.slug,locale,selected.description,true)}}</p><label>{{t('portions')}}<input v-model.number="servings" type="number" min="1" max="30" step="1" required @change="recalculate"></label><div v-if="calculated" class="summary"><strong>{{t('totalCalories',{value:calculated.total.calories})}}</strong><span>{{t('proteinServing',{value:calculated.per_serving.protein_g})}}</span><span>{{calculated.total.price_thb===null?t('priceUnknown'):t('totalPrice',{value:calculated.total.price_thb})}}</span></div><button v-if="store.data&&selected.market===store.data.market.country_code" :disabled="saving||!calculated" @click="logSelected">{{t(saving?'loading':'logPortions',{value:servings})}}</button><RouterLink v-else-if="!store.data" class="inline-link" to="/">{{t('connect')}} →</RouterLink><p v-if="saved" class="success" role="status">{{t(isPublicDemo?'demoRecipeAdded':'recipeAdded')}}</p><h3>{{t('ingredients',{value:servings})}}</h3><p class="hint">{{t('estimateNote')}} {{t(isPublicDemo?'localCalculation':'apiCalculation')}}</p><ul><li v-for="ingredient in ingredientAmounts" :key="ingredient.name">{{ingredientLabel(ingredient.name,locale)}} · {{ingredient.grams}} {{t('grams')}}</li></ul><p class="hint">{{t('preparationState')}}</p></section>
</div></template>
